def backfill_track_stock(apps, schema_editor):
    Item = apps.get_model("inventory", "Item")
    db_alias = schema_editor.connection.alias

    # A PRODUCT that carries a quantity was stock-tracked before this flag
    # existed, so it stays tracked. Everything else starts untracked - including
    # a PRODUCT with no quantity, which the old `stock_tracked()` queryset also
    # excluded, so behaviour is unchanged.
